// Battery total energy
// 72: Total charge Low
// 73: Total charge High
// 74: Total discharge Low
// 75: Total discharge High

msg.baseAddr = 72;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 72,
    quantity: 4
};
return msg;

// Grid and Load total energy
// 78: Grid buy Low
// 79: (skip)
// 80: Grid buy High
// 81: Grid sell Low
// 82: Grid sell High
// 83: (skip)
// 84: (skip)
// 85: Load Low
// 86: Load High

msg.baseAddr = 78;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 78,
    quantity: 9  // 78-86
};
return msg;

// Generator and PV total energy
// 92: Gen Low
// 93: (skip)
// 94: (skip)
// 95: Gen High
// 96: PV Low
// 97: PV High

msg.baseAddr = 92;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 92,
    quantity: 6  // 92-97
};
return msg;

// Build TotalEnergyFlowState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("TotalEnergyFlowState: missing base address");
    return null;
}

// Helper: combine low+high word to 32-bit unsigned, then scale
function u32(low, high) {
    return ((high || 0) << 16) | (low || 0);
}

// ---- Store partials ----

// Battery 72-75
if (baseAddr === 72) {
    const chargeLow = data[0] || 0;      // 72
    const chargeHigh = data[1] || 0;     // 73
    const dischargeLow = data[2] || 0;   // 74
    const dischargeHigh = data[3] || 0;  // 75

    flow.set("tef_part_battery", {
        totalChargeEnergyKWh: Math.round(u32(chargeLow, chargeHigh) * 0.1 * 10) / 10,
        totalDischargeEnergyKWh: Math.round(u32(dischargeLow, dischargeHigh) * 0.1 * 10) / 10
    });
}

// Grid/Load 78-86
else if (baseAddr === 78) {
    // data[0] = 78: Grid buy Low
    // data[1] = 79: (skip)
    // data[2] = 80: Grid buy High
    // data[3] = 81: Grid sell Low
    // data[4] = 82: Grid sell High
    // data[5] = 83: (skip)
    // data[6] = 84: (skip)
    // data[7] = 85: Load Low
    // data[8] = 86: Load High

    const gridBuyLow = data[0] || 0;     // 78
    const gridBuyHigh = data[2] || 0;    // 80
    const gridSellLow = data[3] || 0;    // 81
    const gridSellHigh = data[4] || 0;   // 82
    const loadLow = data[7] || 0;        // 85
    const loadHigh = data[8] || 0;       // 86

    flow.set("tef_part_grid_load", {
        importTotalEnergyKWh: Math.round(u32(gridBuyLow, gridBuyHigh) * 0.1 * 10) / 10,
        exportTotalEnergyKWh: Math.round(u32(gridSellLow, gridSellHigh) * 0.1 * 10) / 10,
        loadTotalEnergyKWh: Math.round(u32(loadLow, loadHigh) * 0.1 * 10) / 10
    });
}

// Gen/PV 92-97
else if (baseAddr === 92) {
    // data[0] = 92: Gen Low
    // data[1] = 93: (skip)
    // data[2] = 94: (skip)
    // data[3] = 95: Gen High
    // data[4] = 96: PV Low
    // data[5] = 97: PV High

    const genLow = data[0] || 0;         // 92
    const genHigh = data[3] || 0;        // 95
    const pvLow = data[4] || 0;          // 96
    const pvHigh = data[5] || 0;         // 97

    flow.set("tef_part_gen_pv", {
        genTotalEnergyKWh: Math.round(u32(genLow, genHigh) * 0.1 * 10) / 10,
        pvTotalEnergyKWh: Math.round(u32(pvLow, pvHigh) * 0.1 * 10) / 10
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const batteryPart = flow.get("tef_part_battery");
const gridLoadPart = flow.get("tef_part_grid_load");
const genPvPart = flow.get("tef_part_gen_pv");

if (!batteryPart || !gridLoadPart || !genPvPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "TotalEnergyFlowState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    deviceId: deviceId,

    grid: {
        importTotalEnergyKWh: gridLoadPart.importTotalEnergyKWh,
        exportTotalEnergyKWh: gridLoadPart.exportTotalEnergyKWh
    },

    pv: {
        totalEnergyKWh: genPvPart.pvTotalEnergyKWh,
        mppt: [
            { id: 1, totalEnergyKWh: null },
            { id: 2, totalEnergyKWh: null },
            { id: 3, totalEnergyKWh: null },
            { id: 4, totalEnergyKWh: null }
        ]
    },

    load: {
        totalEnergyKWh: gridLoadPart.loadTotalEnergyKWh
    },

    battery: {
        totalChargeEnergyKWh: batteryPart.totalChargeEnergyKWh,
        totalDischargeEnergyKWh: batteryPart.totalDischargeEnergyKWh
    },

    generator: {
        totalEnergyKWh: genPvPart.genTotalEnergyKWh
    }
};

// Clear partials
flow.set("tef_part_battery", null);
flow.set("tef_part_grid_load", null);
flow.set("tef_part_gen_pv", null);

flow.set("totalEnergyFlowStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
